            results["vtysh running-config"] = conn.send_command("vtysh -c 'show running-config'", read_timeout=15)
        except Exception as e:
            results["vtysh running-config"] = f"ERROR: {e}"
        conn.disconnect()
    except Exception as e:
        results["CONNECTION_ERROR"] = str(e)
    return name, results

def collect_mikrotik(name, params):
