    for f in as_completed(futs):
        name, data = f.result()
        all_results[name] = data
        print(f"  Done: {name}", file=sys.stderr)

with open("collected_state.json", "w") as f:
    json.dump(all_results, f, indent=2)
print("All done. Output in collected_state.json", file=sys.stderr)

