"""Check current state of all adjacencies and routing after fixes."""
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

time.sleep(30)

def check_vyos(name, host):
    results = {}
    conn = ConnectHandler(host=host, device_type="vyos", username="vyos", password="test")
    for cmd in ["show ip ospf neighbor", "show ip route", "show ip ospf interface"]:
        results[cmd] = conn.send_command(cmd, read_timeout=30)
    if name == "HQ-Edge":
        results["show ip bgp"] = conn.send_command("show ip bgp", read_timeout=15)
        results["show nat source rules"] = conn.send_command("show nat source rules", read_timeout=15)
    conn.disconnect()
    return name, results

def check_mikrotik(name, host):
    results = {}
    conn = ConnectHandler(host=host, device_type="mikrotik_routeros", username="admin", password="test")
    results["neighbors"] = conn.send_command("/routing ospf neighbor print detail")
    results["routes"] = conn.send_command("/ip route print terse")
    results["firewall"] = conn.send_command("/ip firewall filter print terse")
    conn.disconnect()
    return name, results

with ThreadPoolExecutor(max_workers=10) as pool:
    futs = []
    for name, host in [("HQ-Edge","192.168.122.11"),("Hub-A","192.168.122.12"),("Hub-B","192.168.122.13")]:
        futs.append(pool.submit(check_vyos, name, host))
    for name, host in [("Branch-1","192.168.122.21"),("Branch-2","192.168.122.22"),("Branch-3","192.168.122.23"),("Branch-4","192.168.122.24")]:
        futs.append(pool.submit(check_mikrotik, name, host))
    for f in as_completed(futs):
        name, data = f.result()
        print(f"\n===== {name} =====")
        for k, v in data.items():
            print(f"--- {k} ---")
            print(v)

